	@Inject
	public FeatureModelGrammarAccess(GrammarProvider grammarProvider,
			TerminalsGrammarAccess gaTerminals) {
		this.grammar = internalFindGrammar(grammarProvider);
		this.gaTerminals = gaTerminals;
		this.pModel = new ModelElements();
		this.pFeatureModel = new FeatureModelElements();
		this.pBasicConstraint = new BasicConstraintElements();
		this.pFeature = new FeatureElements();
		this.eCrossTreeConstraintType = new CrossTreeConstraintTypeElements();
		this.pFeature_Impl = new Feature_ImplElements();
		this.pEString = new EStringElements();
		this.pEBoolean = new EBooleanElements();
		this.pAlternative = new AlternativeElements();
		this.pOrGroup = new OrGroupElements();
	}
	
	protected Grammar internalFindGrammar(GrammarProvider grammarProvider) {
		Grammar grammar = grammarProvider.getGrammar(this);
		while (grammar != null) {
			if ("eu.coresense.variability.FeatureModel".equals(grammar.getName())) {
				return grammar;
			}
			List<Grammar> grammars = grammar.getUsedGrammars();
			if (!grammars.isEmpty()) {
				grammar = grammars.iterator().next();
			} else {
				return null;
			}
		}
		return grammar;
	}
	
	@Override
	public Grammar getGrammar() {
		return grammar;
	}
	
	
	public TerminalsGrammarAccess getTerminalsGrammarAccess() {
		return gaTerminals;
	}

	
